package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for {@link SimpleType#_narrow(Class)}.
 * Since the method is protected, we use reflection to access it.
 */
public class SimpleType__narrow_TriageGen1Test {

    @SuppressWarnings("unchecked")
    private <T> T invokeNarrow(SimpleType type, Class<?> subclass) throws Exception {
        Method method = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        method.setAccessible(true);
        return (T) method.invoke(type, subclass);
    }

    @Test
    public void testNarrow_SameClassReturnsThis() throws Exception {
        TypeFactory<?> tf = TypeFactory.defaultInstance();
        SimpleType type = tf.constructType(String.class);

        // When subclass is the same as the current class, it should return 'this'
        SimpleType result = invokeNarrow(type, String.class);

        assertSame("Should return the exact same instance when classes match", type, result);
    }

    @Test
    public void testNarrow_DifferentClassReturnsNewSimpleType() throws Exception {
        TypeFactory<?> tf = TypeFactory.defaultInstance();
        SimpleType type = tf.constructType(Object.class);

        // When subclass is different, it should return a new SimpleType instance
        SimpleType result = invokeNarrow(type, String.class);

        // Verify it's a different instance but represents the new class
        org.junit.Assert.assertNotSame(type, result);
        assertEquals(String.class, result.getRawClass());

        // Verify internal properties are propagated (via equality or checking properties)
        // Since we can't easily access protected fields without reflection, 
        // we verify the behavior through the returned type's raw class.
        assertEquals("The new type should represent the subclass", String.class, result.getRawClass());
    }

    @Test
    public void testNarrow_WithSubclassHierarchy() throws Exception {
        TypeFactory<?> tf = TypeFactory.defaultInstance();
        // Start with a base type
        SimpleType baseType = tf.constructType(Number.class);

        // Narrow to an Integer
        SimpleType result = invokeNarrow(baseType, Integer.class);

        org.junit.Assert.assertNotSame(baseType, result);
        assertEquals(Integer.class, result.getRawClass());
    }

    @Test
    public void testNarrow_WithInterface() throws Exception {
        TypeFactory<?> tf = TypeFactory.defaultInstance();
        // Start with a type that is an interface
        SimpleType baseType = tf.constructType(Serializable.class);

        // Narrow to a class that implements the interface
        SimpleType result = invokeNarrow(baseType, String.class);

        org.junit.Assert.assertNotSame(baseType, result);
        assertEquals(String.class, result.getRawClass());
    }
}
